spec.fn:
flow_input = flow["input"] or {}
tables = flow_input.get("retrieved_tables")
if isinstance(tables, dict):
    tables = tables.get("output")
if not isinstance(tables, list):
    tables = []

identifier = flow["input"].get("identifier")

# Best-effort int, 0 on missing/unparseable.
def as_int(value):
    try:
        return int(value)
    except (TypeError, ValueError):  # fmt: skip
        return 0

# DB rows arrive typed, CSV-style rows arrive as strings.
def as_bool(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() in ("true", "1", "yes", "t")
    return bool(value)

# Tags are stored as JSON-array strings ('["a","b"]') but may also arrive
# as a real list, empty, or "[]". Normalise to a list or None.
def parse_tags(value):
    if value is None:
        return None
    if isinstance(value, list):
        return value or None
    if isinstance(value, str):
        s = value.strip()
        if s in ("", "[]"):
            return None
        try:
            parsed = json.loads(s)
        except ValueError:
            return None
        return parsed if isinstance(parsed, list) and parsed else None
    return None

by_table = {t.get("table"): (t.get("rows") or []) for t in tables}
scoring = by_table.get("scoring") or []
details = by_table.get("details") or []
quiz_meta = by_table.get("quiz_meta") or []

# Step 1: quiz context keyed by quiz_id, nesting the flat prize.* columns
# into a `prize` object.
ctx = {}
for m in quiz_meta:
    qid = m.get("quiz_id")
    if qid is None:
        continue
    prize = {
        "prize_name": m.get("prize.prize_name") or None,
        "prize_url": m.get("prize.prize_url") or None,
        "prize_value": m.get("prize.prize_value") or None,
        "prize_currency": m.get("prize.prize_currency") or None,
        "prize_description": m.get("prize.prize_description") or None,
    }
    if not any(prize.values()):
        prize = None
    ctx[qid] = {
        "account_id": m.get("account_id"),
        "title": m.get("title"),
        "status": m.get("status"),
        "brand_name": m.get("brand_name"),
        "brand_tags": parse_tags(m.get("brand_tags")),
        "language": m.get("language"),
        "prize": prize,
        "prize_type": parse_tags(m.get("prize_type")),
    }

# Step 2: answers grouped by submission_id.
answers_by_sub = {}
for d in details:
    sid = d.get("submission_id")
    if sid is None:
        continue
    answers_by_sub.setdefault(sid, []).append(
        {
            "submission_id": sid,
            "question": d.get("question"),
            "answer": d.get("answer"),
            "correct": as_bool(d.get("correct")),
        }
    )

# Step 3: group scoring by respondent (email), bucketing per quiz. One
# scoring row == one submission. `quiz_index` maps quiz_id -> bucket within
# the current respondent, so repeat submissions accumulate rather than
# opening a second bucket for the same quiz.
profiles = {}
order = []
for s in scoring:
    email = s.get("email")
    key = email if email is not None else s.get("submission_id")
    if key not in profiles:
        profiles[key] = {
            "respondent_id": s.get("submission_id"),
            # Sourced from quiz_meta via ctx (scoring rows carry no
            # account_id); filled from the first quiz row that resolves.
            "account_id": None,
            "identity": {
                "display_name": s.get("display_name"),
                "email": email,
                "anonymous": as_bool(s.get("anonymous")),
                "is_owner": as_bool(s.get("is_owner")),
                "placeholder_email": bool(email)
                and email.startswith("temp@"),
            },
            "quiz_index": {},
            "quizzes": [],
        }
        order.append(key)
    prof = profiles[key]

    # anonymous / is_owner: any true across the respondent's rows wins.
    if as_bool(s.get("anonymous")):
        prof["identity"]["anonymous"] = True
    if as_bool(s.get("is_owner")):
        prof["identity"]["is_owner"] = True

    # Resolve (or create) this row's quiz bucket, pulling meta from ctx.
    qid = s.get("quiz_id")
    if qid not in prof["quiz_index"]:
        meta = ctx.get(qid) or {}
        if prof["account_id"] is None:
            prof["account_id"] = meta.get("account_id")
        bucket = {
            "quiz_id": qid,
            "title": meta.get("title"),
            "brand_name": meta.get("brand_name"),
            "brand_tags": meta.get("brand_tags"),
            "language": meta.get("language"),
            "prize": meta.get("prize"),
            "prize_type": meta.get("prize_type"),
            "correct": 0,
            "incorrect": 0,
            "time_seconds": 0,
            "submissions": [],
            "answers": [],
        }
        prof["quiz_index"][qid] = bucket
        prof["quizzes"].append(bucket)
    bucket = prof["quiz_index"][qid]

    # Metrics for THIS submission, summed into the bucket.
    c = as_int(s.get("correct_answers"))
    i = as_int(s.get("incorrect_answers"))
    t = as_int(s.get("completion_time"))
    bucket["correct"] += c
    bucket["incorrect"] += i
    bucket["time_seconds"] += t

    # One submission entry + its joined answers.
    sid = s.get("submission_id")
    bucket["submissions"].append(
        {
            "submission_id": sid,
            "submitted_at": s.get("submitted_at"),
            "correct": c,
            "incorrect": i,
            "time_seconds": t,
        }
    )
    for a in answers_by_sub.get(sid, []):
        bucket["answers"].append(a)

# Step 4: finalize each profile -- per-quiz accuracy, counts, drop scratch.
records = []
for key in order:
    prof = profiles[key]
    del prof["quiz_index"]
    for q in prof["quizzes"]:
        answered = q["correct"] + q["incorrect"]
        q["answered"] = answered
        q["accuracy"] = (
            round(q["correct"] / answered, 4) if answered > 0 else None
        )
    prof["quizzes_num"] = len(prof["quizzes"])
    prof["context_record_id"] = (
        identifier if identifier is not None else prof["respondent_id"]
    )
    prof["analysis"] = {}
    records.append(prof)

self.output.base_profiles = records
self.output.profiles_num = len(records)
self.output.uploaded_num = 0
self.output.preview_inputs = flow_input

flow.private.base_profiles = records

profile = dict(parent._current_item or {}) or {}

# Flatten the nested profile back to the one-row-per-submission shape this block scores.
rows = []
for q in profile.get("quizzes") or []:
    qid = q.get("quiz_id")
    if qid is None:
        continue
    for s in q.get("submissions") or []:
        rows.append(
            {
                "quiz_id": qid,
                "submitted_at": s.get("submitted_at"),
                "_id": s.get("submission_id"),
            }
        )

identifier = profile.get("respondent_id")

# Flow input variables to adjust the behavior of the node at runtime.
criteria = flow.input.get("sustained_engagement_level_criteria") or {}

# number_of_quizzes is PER SUB-PERIOD, so each level is a denser rhythm over the same month: 1/week = 4 a month, 2/week = 8, 3/week = 12.
levels = criteria.get("levels") or [
    {
        "level": "1",
        "timeframe_days": 30,
        "min_days_between": 7,
        "number_of_quizzes": 1,
    },
    {
        "level": "2",
        "timeframe_days": 30,
        "min_days_between": 7,
        "number_of_quizzes": 2,
    },
    {
        "level": "3",
        "timeframe_days": 30,
        "min_days_between": 7,
        "number_of_quizzes": 3,
    },
]

# ISO date -> integer day count, so date gaps become plain subtraction. Only the leading YYYY-MM-DD is read, so full timestamps work too.
def epoch_day(value):
    if not value:
        return None
    try:
        return datetime.date.fromisoformat(value[:10]).toordinal()
    except ValueError:
        return None

# One completion per distinct quiz_id -- its earliest submission, carrying the named `extra` fields from that same row.
def earliest_completions(
    rows, key="quiz_id", date_field="submitted_at", extra=()
):
    out = {}
    for row in rows:
        key_val = row.get(key)
        day = epoch_day(row.get(date_field))
        if key_val is None or day is None:
            continue
        current = out.get(key_val)
        if current is None or day < current["epoch_day"]:
            record = {"epoch_day": day}
            for field in extra:
                record[field] = row.get(field)
            out[key_val] = record
    return out

# Does a window starting at `start` sustain the cadence? The window is cut into consecutive `gap`-day sub-periods and EVERY one must hold at least `per_period` completions -- a burst in a single sub-period fails, which is what separates sustained engagement from one busy week.
def sustains_cadence(sorted_days, start, window, gap, per_period):
    periods = window // gap
    if periods <= 0:
        return False
    for p in range(periods):
        lo = start + p * gap
        hi = lo + gap
        found = 0
        for day in sorted_days:
            if lo <= day < hi:
                found += 1
            elif day >= hi:
                break
        if found < per_period:
            return False
    return True

# Step 1: one completion per quiz, as a sorted list of day counts.
earliest = earliest_completions(rows)
ordinals = sorted(rec["epoch_day"] for rec in earliest.values())

# Step 2: rank every passing bracket so a plain sort picks the winner. Key = [total, gap, -window, -idx, level]; ascending sort + take the last => most quizzes demanded, then widest gap, then narrowest window, then the earlier-listed bracket. A bracket passes when SOME window anchored on a completion sustains its cadence end to end.
ranked = []
for idx, b in enumerate(levels):
    per_period = int(b.get("number_of_quizzes") or 1)
    gap = int(b.get("min_days_between") or 0)
    window = int(b.get("timeframe_days") or 0)
    if gap <= 0 or window <= 0:
        continue
    # Anchoring on each completion is enough: a qualifying window can always
    # be slid forward until its first sub-period starts on a completion.
    if any(
        sustains_cadence(ordinals, start, window, gap, per_period)
        for start in ordinals
    ):
        total = (window // gap) * per_period
        ranked.append([total, gap, -window, -idx, str(b.get("level"))])

# Step 3: winner is the top-ranked bracket's level (None if none passed).
winner = sorted(ranked)[-1] if ranked else None
level = int(winner[4]) if winner else None

# Plain-language restatement of the winning bracket, so consumers see why the level was awarded and not just the number.
def describe(bracket):
    per_period = int(bracket.get("number_of_quizzes") or 1)
    gap = int(bracket.get("min_days_between") or 0)
    window = int(bracket.get("timeframe_days") or 0)
    periods = window // gap if gap > 0 else 0
    quizzes = "1 quiz" if per_period == 1 else f"{per_period} quizzes"
    days = "day" if gap == 1 else f"{gap} days"
    return (
        f"Completes at least {quizzes} every {days} for {window} days "
        f"running ({periods * per_period} in total)."
    )

# Key position 3 holds -idx, so negating it indexes back into `levels`.
rule_description = describe(levels[-winner[3]]) if winner else None

# The flow's identifier wins; the first submission's id is the fallback.
respondent_id = (
    identifier
    if identifier is not None
    else (rows[0].get("_id") if rows else None)
)
result = {
    "respondent_id": respondent_id,
    "sustained_engagement_level": level if level is not None else 0,
    "rule_description": rule_description,
}

# Each field is published three ways -- raw, wrapped as a single-key dict, and inside `result` -- so a data map can bind whichever shape it needs.
self.output.respondent_id = respondent_id

self.output.sustained_engagement_level = level
self.output.sustained_engagement_level_obj = {
    "sustained_engagement_level": level
}

self.output.result = result
self.output.preview_inputs = profile

profile = dict(parent._current_item or {}) or {}

# Flatten the nested profile into submission rows plus per-quiz context.
# prize_name lives one level in, at quiz["prize"]["prize_name"].
rows = []
ctx = {}
for q in profile.get("quizzes") or []:
    qid = q.get("quiz_id")
    if qid is None:
        continue
    prize = q.get("prize") or {}
    ctx[qid] = {
        "brand_name": q.get("brand_name"),
        "prize_name": prize.get("prize_name"),
    }
    for s in q.get("submissions") or []:
        correct = int(s.get("correct") or 0)
        incorrect = int(s.get("incorrect") or 0)
        rows.append(
            {
                "quiz_id": qid,
                "submitted_at": s.get("submitted_at"),
                "correct_answers": correct,
                "total_answered": correct + incorrect,
                "_id": s.get("submission_id"),
            }
        )

identifier = profile.get("respondent_id")

# Flow input variables to adjust the behavior of the node at runtime.
criteria = flow.input.get("likely_long_term_brand_fan_criteria") or {}

window_days = int(criteria.get("window_days") or 30)
min_quizzes = int(criteria.get("min_quizzes") or 2)
success_pct = float(criteria.get("success_pct") or 60)

# ISO date -> integer day count, so date gaps become plain subtraction.
# Only the leading YYYY-MM-DD is read, so full timestamps work too.
def epoch_day(value):
    if not value:
        return None
    try:
        return datetime.date.fromisoformat(value[:10]).toordinal()
    except ValueError:
        return None

# One completion per distinct quiz_id -- its earliest submission, carrying
# the named `extra` fields (here the score) from that same row.
def earliest_completions(rows, key="quiz_id", date_field="submitted_at", extra=()):
    out = {}
    for row in rows:
        key_val = row.get(key)
        day = epoch_day(row.get(date_field))
        if key_val is None or day is None:
            continue
        current = out.get(key_val)
        if current is None or day < current["epoch_day"]:
            record = {"epoch_day": day}
            for field in extra:
                record[field] = row.get(field)
            out[key_val] = record
    return out

# 100 * sum(correct)/sum(answered). None when nothing was answered, so
# "no data" stays distinct from a real 0%.
def pooled_success_rate(items, correct_field="correct", answered_field="answered"):
    correct = sum(int(i.get(correct_field) or 0) for i in items)
    answered = sum(int(i.get(answered_field) or 0) for i in items)
    if answered <= 0:
        return None
    return 100.0 * correct / answered

# Step 1: one completion per quiz, keeping its date + score.
completions = earliest_completions(
    rows, extra=["correct_answers", "total_answered"]
)

# Step 2: per-quiz record (day, brand, prize, correct, answered).
# `answered` falls back to `correct` when total_answered is absent.
quiz = {}
for quiz_id, c in completions.items():
    correct = int(c.get("correct_answers") or 0)
    answered_raw = c.get("total_answered")
    answered = int(answered_raw) if answered_raw is not None else correct
    meta = ctx.get(quiz_id) or {}
    quiz[quiz_id] = {
        "ord": c["epoch_day"],
        "brand": meta.get("brand_name"),
        "prize_name": meta.get("prize_name"),
        "correct": correct,
        "answered": answered,
    }

# Step 3: group the distinct quizzes by brand (skip unknown brands).
by_brand = {}
for q in quiz.values():
    if q["brand"] is None:
        continue
    by_brand.setdefault(q["brand"], []).append(q)

# Step 4: evaluate EVERY brand and describe the ones that qualify. The
# window test only decides IF a brand qualifies; the reported stats then
# summarise all of that brand's distinct completed quizzes.
brands = []
for brand_name, qs in sorted(by_brand.items()):
    ords = [q["ord"] for q in qs]
    qualifies = False
    for anchor in ords:
        win = [
            q
            for q in qs
            if q["ord"] >= anchor and (q["ord"] - anchor) <= window_days
        ]
        if len(win) >= min_quizzes:
            rate = pooled_success_rate(win)
            if rate is not None and rate > success_pct:
                qualifies = True
                break
    if not qualifies:
        continue

    # Prizes this respondent actually played for under this brand:
    # de-duplicated, blanks dropped, first-seen order preserved.
    prizes = []
    for q in sorted(qs, key=lambda q: q["ord"]):
        name = q.get("prize_name")
        if name and name not in prizes:
            prizes.append(name)

    overall = pooled_success_rate(qs)
    brands.append(
        {
            brand_name: {
                # Pooled across the brand's distinct quizzes, as a
                # percentage rounded to 2dp. None only if nothing answered.
                "average_success_rate": (
                    round(overall, 2) if overall is not None else None
                ),
                "total_completed_quizzes": len(qs),
                "prizes_played_for": prizes,
            }
        }
    )

# The flow's identifier wins; the first submission's id is the fallback.
respondent_id = (
    identifier if identifier is not None else (rows[0].get("_id") if rows else None)
)
result = {
    "respondent_id": respondent_id,
    "likely_long_term_brand_fan": brands,
}

# Each field is published three ways -- raw, wrapped as a single-key dict,
# and inside `result` -- so a data map can bind whichever shape it needs.
self.output.respondent_id = respondent_id

self.output.likely_long_term_brand_fan = brands
self.output.likely_long_term_brand_fan_obj = {"likely_long_term_brand_fan": brands}

self.output.result = result
self.output.preview_inputs = profile

enriched_profile = dict(
    parent.stage_profile_inputs.output.profile or {}
)

### Ay additional scorer nodes added should be appended into scorers
scorers = {
    "sustained_engagement_level": (
        parent.sustained_engagement_level.output.result or {}
    ),
    "likely_long_term_brand_fan": (
        parent.likely_long_term_brand_fan.output.result or {}
    ),
}
inputs = dict(scorers or {})
### ---------------------------------------------------------------

analysis = {}
for scorer_name, result in inputs.items():
    if result is None:
        continue
    if isinstance(result, dict) and isinstance(
        result.get("result"), dict
    ):
        result = result["result"]
    analysis[scorer_name] = result

enriched_profile["analysis"] = analysis

self.output.enriched_profile = enriched_profile
self.output.preview_inputs = inputs

# The foreach exposes no readable aggregate of its iterations, so each
# iteration appends its own record to the flow-scoped list that
# build_profile_table reads once the loop is done.
collected = flow["private"].get("enriched_profiles") or []
flow.private.enriched_profiles = collected + [enriched_profile]

inputs = (
    {"rows": parent.each_respondent.merge_profile_signals.output}
    if isinstance(
        parent.each_respondent.merge_profile_signals.output, list
    )
    else (
        parent.each_respondent.merge_profile_signals.output
        if isinstance(
            parent.each_respondent.merge_profile_signals.output, dict
        )
        else {}
    )
)
rows_in = inputs.get("rows")

# Tolerate the bare list and the {rows: [...]} / {items: [...]} wrappers.
if isinstance(rows_in, dict):
    for key in ("rows", "items", "output", "result"):
        if isinstance(rows_in.get(key), list):
            rows_in = rows_in[key]
            break
if not isinstance(rows_in, list):
    rows_in = []

# The mapped input is the fallback, not the primary source: the foreach exposes no readable aggregate, so the records actually arrive via the flow-scoped list each iteration appended to.
if not rows_in:
    collected = flow["private"].get("enriched_profiles")
    if isinstance(collected, list):
        rows_in = collected

DECOMPOSE = ("analysis", "identity")

rows_out = []
for entry in rows_in:
    if not isinstance(entry, dict):
        continue

    row = {}
    for key, value in entry.items():
        # One level only: each child becomes `key.child`, and whatever
        # the child holds is left exactly as it is.
        if key in DECOMPOSE and isinstance(value, dict):
            for sub_key, sub_value in value.items():
                row[f"{key}.{sub_key}"] = sub_value
        else:
            row[key] = value

    rows_out.append(row)

self.output.rows = rows_out
self.output.row_count = len(rows_out)
self.output.enriched_profiles = rows_in
self.output.preview_inputs = inputs
